#effect Duotono
#desc Sombras y luces con dos colores
#input A Imagen

#color sombra #1a0b3d
#color luz #ffb36b
#param contraste 1.2 0 3

float l = luma(@A.rgb);
l = clamp((l - 0.5) * @contraste + 0.5, 0.0, 1.0);
@out.rgb = mix(@sombra, @luz, l);

#effect Grano y viñeta
#desc Grano animado de película con viñeta
#input A Imagen

#param grano 0.08 0 0.5
#param vig 1.2 0 3

vec2 d = @uv - 0.5;
d.x *= @res.x / @res.y;
float n = hash13(vec3(@P, floor(@time * 24.0))) - 0.5;
@out.rgb += n * @grano;
@out.rgb *= 1.0 - @vig * dot(d, d);

#effect Pixelado
#desc Bloques cuadrados de tamaño ajustable
#input A Imagen

#param bloque 12 2 64

vec2 cell = vec2(@bloque) / @res;
vec2 uv = (floor(@uv / cell) + 0.5) * cell;
@out = A(uv);

#effect Semitono
#desc Puntos de imprenta según la luminancia
#input A Imagen

#param celda 10 4 40
#param angulo 45 0 90
#color tinta #111111
#color papel #f4efe4

float a = radians(@angulo);
mat2 R = mat2(cos(a), -sin(a), sin(a), cos(a));
vec2 p = R * @P;
vec2 id = floor(p / @celda);
vec2 f = fract(p / @celda) - 0.5;
vec2 centro = transpose(R) * ((id + 0.5) * @celda);
float l = luma(A(centro / @res).rgb);
float r = sqrt(1.0 - l) * 0.75;
float punto = 1.0 - smoothstep(r - 0.06, r + 0.06, length(f));
@out = vec4(mix(@papel, @tinta, punto), 1.0);

#effect Pantalla CRT
#desc Curvatura de barril y líneas de barrido
#input A Imagen

#param curva 0.12 0 0.4
#param lineas 0.35 0 1

vec2 c = @uv * 2.0 - 1.0;
c *= 1.0 + @curva * dot(c, c) * 0.5;
vec2 uv = c * 0.5 + 0.5;
if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
  @out = vec4(0.0, 0.0, 0.0, 1.0);
} else {
  vec4 col = A(uv);
  float s = 0.5 + 0.5 * sin(uv.y * @res.y * 3.14159);
  col.rgb *= 1.0 - @lineas * (1.0 - s);
  @out = col;
}

#effect Ondas
#desc Deformación ondulante animada
#input A Imagen

#param amp 0.01 0 0.05
#param freq 18 1 80
#param vel 2 0 10

vec2 uv = @uv;
uv.x += sin(uv.y * @freq + @time * @vel) * @amp;
uv.y += cos(uv.x * @freq * 0.7 + @time * @vel) * @amp;
@out = A(uv);

#effect Caleidoscopio
#desc Simetría radial de N segmentos
#input A Imagen

#param segmentos 6 2 16
#param giro 0 0 6.2832

vec2 p = @uv - 0.5;
p.x *= @res.x / @res.y;
float r = length(p);
float a = atan(p.y, p.x) + @giro;
float seg = 6.28318 / floor(@segmentos);
a = abs(mod(a, seg) - seg * 0.5);
p = vec2(cos(a), sin(a)) * r;
p.x /= @res.x / @res.y;
@out = A(p + 0.5);

#effect Bordes neón
#desc Contornos Sobel brillantes sobre la imagen oscurecida
#input A Imagen

#color neon #00f0ff
#param fuerza 3 0 10
#param fondo 0.25 0 1

// Luminancia de A desplazada (dx, dy) píxeles
float L(float dx, float dy) {
  return luma(A(@uv + vec2(dx, dy) / @res).rgb);
}

float gx = L(1.0, 1.0) + 2.0 * L(1.0, 0.0) + L(1.0, -1.0)
         - L(-1.0, 1.0) - 2.0 * L(-1.0, 0.0) - L(-1.0, -1.0);
float gy = L(-1.0, 1.0) + 2.0 * L(0.0, 1.0) + L(1.0, 1.0)
         - L(-1.0, -1.0) - 2.0 * L(0.0, -1.0) - L(1.0, -1.0);
float e = clamp(length(vec2(gx, gy)) * @fuerza, 0.0, 1.0);
@out.rgb = @A.rgb * @fondo + @neon * e;

#effect Desenfoque radial
#desc Zoom borroso hacia un centro ajustable
#input A Imagen

#param fuerza 0.15 0 0.5
#param cx 0.5 0 1
#param cy 0.5 0 1

vec2 c = vec2(@cx, @cy);
vec4 acc = vec4(0.0);
for (int i = 0; i < 24; i++) {
  float k = float(i) / 23.0;
  acc += A(mix(@uv, c, k * @fuerza));
}
@out = acc / 24.0;

#effect Mezcla con máscara
#desc Funde A y B según un atributo de C
#input A Imagen 1
#input B Imagen 2
#input C Máscara scalar

#param suavidad 0.1 0 0.5
#param umbral 0.5 0 1

// @Cv = canal elegido de C (luminancia por defecto); sin conectar vale 1
float m = smoothstep(@umbral - @suavidad, @umbral + @suavidad, @Cv);
@out = mix(@A, @B, m);

#effect Plasma
#desc Generador animado de color, sin entradas

#param escala 3 0.5 12
#param vel 0.6 0 3

vec2 p = (@uv - 0.5) * vec2(@res.x / @res.y, 1.0) * @escala;
float t = @time * @vel;
float v = sin(p.x + t) + sin(p.y * 1.3 - t) + sin(length(p) * 1.7 + t * 1.4);
v += fbm(vec3(p * 0.6, t * 0.3), 4) * 2.0;
vec3 col = hsv2rgb(vec3(fract(v * 0.15 + t * 0.05), 0.75, 0.95));
@out = vec4(col, 1.0);

#effect Pulso
#desc Zoom y brillo que laten con los graves del audio
#input A Imagen
#input B Audio

#param zoom 0.08 0 0.3
#param brillo 0.6 0 2
#color destello #ffd9a0

// Conecta un nodo Audio (capa «Valores») a la entrada B:
// @B.r = volumen, @B.g = graves, @B.b = agudos
float graves = @B.g;
vec2 c = @uv - 0.5;
vec4 col = A(0.5 + c / (1.0 + @zoom * graves));
col.rgb += @destello * @brillo * graves * graves;
@out = vec4(col.rgb, col.a);

#effect Anaglifo 3D
#desc Fusiona el ojo izquierdo (rojo) y el derecho (cian) como el cine 3D clásico
#input A Ojo izquierdo
#input B Ojo derecho
#input C Profundidad scalar

#enum modo Color | Grises | Optimizado (Dubois)
#param separacion 6 -40 40
#color izquierda #ff0000
#color derecha #00ffff

// A = ojo izquierdo, B = ojo derecho. Si B no está conectada, el par se
// inventa desplazando A. Con un mapa en C (claro = cerca), el desplazamiento
// cambia por píxel y la imagen gana relieve.
float k = uHasC > 0.5 ? (@Cv - 0.5) * 2.0 : 1.0;
vec2 off = vec2(@separacion * k * 0.5 / @res.x, 0.0);
vec4 L = A(@uv + off);
vec4 R = uHasB > 0.5 ? B(@uv - off) : A(@uv - off);

vec3 col;
if (@modo == 1) {
  // Grises: menos rivalidad de color, más cómodo de ver
  col = luma(L.rgb) * @izquierda + luma(R.rgb) * @derecha;
} else if (@modo == 2) {
  // Matrices de Dubois para rojo/cian: menos "fantasmas"
  col = vec3(
    dot(L.rgb, vec3( 0.456,  0.500,  0.176)) + dot(R.rgb, vec3(-0.043, -0.088, -0.002)),
    dot(L.rgb, vec3(-0.040, -0.038, -0.016)) + dot(R.rgb, vec3( 0.378,  0.734, -0.018)),
    dot(L.rgb, vec3(-0.015, -0.021, -0.005)) + dot(R.rgb, vec3(-0.072, -0.113,  1.226)));
} else {
  // Color: cada ojo pasa por su filtro
  col = L.rgb * @izquierda + R.rgb * @derecha;
}
@out = vec4(clamp(col, 0.0, 1.0), max(L.a, R.a));

#effect VHS
#desc Líneas de barrido, color corrido, tracking y ruido de cinta VHS
#input A Imagen

#param lineas 0.35 0 1
#param grosor 2 1 6
#param sangrado 8 0 24
#param desfase 3 -12 12
#param temblor 1.5 0 8
#param tracking 0.6 0 1
#param cabeza 1 0 1
#param ruido 0.08 0 0.4
#param saturacion 0.85 0 1.5

// YIQ: el espacio de color de la TV analógica (Y = brillo, I/Q = color)
vec3 rgb2yiq(vec3 c) {
  return mat3(0.299, 0.596, 0.211,
              0.587, -0.274, -0.523,
              0.114, -0.322, 0.312) * c;
}
vec3 yiq2rgb(vec3 c) {
  return mat3(1.0, 1.0, 1.0,
              0.956, -0.272, -1.106,
              0.621, -0.647, 1.703) * c;
}

float px = 1.0 / @res.x;
float linea = floor(@P.y / @grosor);
float cuadro = floor(@time * 30.0);

// Temblor por línea + ondulación lenta de la cinta (en píxeles)
float dx = (hash13(vec3(linea, cuadro, 3.1)) - 0.5) * @temblor;
dx += sin(@uv.y * 40.0 + @time * 3.0) * @temblor * 0.4;

// Banda de tracking que sube rodando
float pos = fract(@time * 0.12);
float banda = (1.0 - smoothstep(0.0, 0.035, abs(@uv.y - pos))) * @tracking;
dx += banda * (hash13(vec3(linea, cuadro, 7.7)) - 0.3) * 40.0;

// Ruido de cambio de cabeza en el borde inferior
float cab = smoothstep(0.035, 0.0, @uv.y) * @cabeza;
dx += cab * 25.0 * (1.0 + hash13(vec3(linea, cuadro, 9.0)));

vec2 uv = @uv + vec2(dx * px, 0.0);

// Brillo nítido; color desenfocado y corrido en horizontal
float Y = rgb2yiq(A(uv).rgb).x;
vec2 IQ = vec2(0.0);
for (int i = 0; i < 8; i++) {
  float o = (float(i) / 7.0 - 0.5) * @sangrado + @desfase;
  IQ += rgb2yiq(A(uv + vec2(o * px, 0.0)).rgb).yz;
}
IQ = IQ / 8.0 * @saturacion;
vec3 col = yiq2rgb(vec3(Y, IQ));

// Líneas de barrido
float sl = 0.5 + 0.5 * cos(@P.y / @grosor * 6.28318);
col *= 1.0 - @lineas * (1.0 - sl);

// Ruido de señal, nieve en la banda de tracking y en la franja inferior
col += (hash13(vec3(@P, cuadro)) - 0.5) * @ruido;
col += banda * hash13(vec3(floor(@P.x * 0.5), linea, cuadro)) * 0.35;
col += cab * hash13(vec3(@P, cuadro + 1.0)) * 0.3;

@out = vec4(clamp(col, 0.0, 1.0), 1.0);
